vec3 tone(float idx, float band) {
    if (idx < 0.5) return band < 0.5 ? vec3(0.1, 0.05, 0.3) : (band < 1.5 ? vec3(1.0, 0.2, 0.55) : vec3(1.0, 0.9, 0.2));
    if (idx < 1.5) return band < 0.5 ? vec3(0.0, 0.2, 0.25) : (band < 1.5 ? vec3(0.1, 0.8, 0.7) : vec3(1.0, 0.55, 0.1));
    if (idx < 2.5) return band < 0.5 ? vec3(0.25, 0.0, 0.05) : (band < 1.5 ? vec3(0.95, 0.3, 0.1) : vec3(0.5, 0.9, 1.0));
    return band < 0.5 ? vec3(0.05, 0.1, 0.05) : (band < 1.5 ? vec3(0.6, 0.2, 0.9) : vec3(0.7, 1.0, 0.3));
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 cell = floor(uv * 2.0);
    vec2 p = fract(uv * 2.0);
    vec3 c = texture(iChannel0, p).rgb;
    float l = dot(c, vec3(0.299, 0.587, 0.114));
    float band = l < U.p0.x ? 0.0 : (l < U.p0.y ? 1.0 : 2.0);
    vec3 col = tone(cell.x + cell.y * 2.0, band);
    vec2 d = fract(fragCoord / 6.0) - 0.5;
    col *= 0.9 + 0.1 * step(length(d), 0.35);
    fragColor = vec4(col, 1.0);
}
